class Solution {
public:
    int leftMostColumnWithOne(BinaryMatrix &binaryMatrix) {
        vector<int> dims = binaryMatrix.dimensions();
        int rows = dims[0], cols = dims[1];
        int r = 0, c = cols - 1;
        int ans = -1;
        while (r < rows && c >= 0) {
            if (binaryMatrix.get(r, c) == 1) {
                ans = c;
                c--;
            } else {
                r++;
            }
        }
        return ans;
    }
};

interface BinaryMatrix {
    public int get(int row, int col);
