var leftMostColumnWithOne = function(binaryMatrix) {
    const [rows, cols] = binaryMatrix.dimensions();
    let r = 0, c = cols - 1;
    let ans = -1;
    while (r < rows && c >= 0) {
        if (binaryMatrix.get(r, c) === 1) {
            ans = c;
            c--;
        } else {
            r++;
        }
    }
    return ans;
};
